"""Manual original-abstract interpretations for root-assignment entries 114:150."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
NOTES={}
def add(d):NOTES.update(d)
add({
114:('Can wearable ECG age indicate atrial-fibrillation presence and burden?','A residual network trained on one million ECGs uses GAN-derived single-lead signals and independent wearable validation.','Age-estimation errors were roughly 10–12 years; larger ECG-age gaps were associated with AF presence and higher burden across two cohorts.','Associations do not establish prospective AF prevention, and synthetic training signals may differ from actual wearable recordings.'),
115:('Does a messaging-based AI agent improve orthopedic postoperative care?','A randomized trial compared GPT-4 support through WeChat with routine doctor-led communication in 261 patients.','AI responded much faster and improved early function and satisfaction, but response accuracy was slightly lower and six-month outcomes were similar.','Short-term benefits did not persist as significant between-group differences; AI support still requires attention to erroneous advice.'),
116:('Which cell programs accompany fatty-liver progression to steatohepatitis?','Integrated single-cell, spatial, and bulk transcriptomics are combined with ensemble machine-learning biomarker prediction.','DTNA-positive macrophages and stellate-cell interactions implicated a RUNX2-related fibrotic axis; classification of disease stages averaged AUC 0.839.','Public-data associations and inferred cell communication nominate mechanisms rather than proving causality or validating a noninvasive clinical test.'),
117:('Can remote cognitive testing detect dementia-related impairment across languages and ages?','Four OCTAL browser-based validation studies evaluated cognitive tasks, clinical discrimination, and reliability in 1,664 participants.','In a 194-person memory-clinic cohort, brief and extended assessments achieved Alzheimer-versus-subjective-decline AUCs of 0.92 and 0.97, with good retest reliability.','The abstract describes digital testing rather than a substantive learned-AI model; clinic discrimination does not establish population screening utility.'),
118:('Can pathology classifiers remain reliable across scanners and institutions?','StructMIL combines tissue graphs, prototype pooling, contrastive alignment, adversarial confusion, and consistency training.','Camelyon16 cross-center AUC reached 0.967, while PANDA grading improved kappa relative to prior multiple-instance approaches under scanner shifts.','Benchmark domain-shift robustness and attribution maps do not establish prospective diagnostic safety across all new clinical sites.'),
119:('Can continuous lesion representations capture stroke detail missed by binary masks?','StrokeFlow predicts an ischemic density field and an ADC-gradient-supervised vector field from diffusion MRI.','ISLES 2022 evaluation improved boundary-distance metrics and sensitivity to small or multifocal lesions over compared segmentation baselines.','ADC-aligned vector fields are modeled imaging representations, not direct measurements of perfusion dynamics or evidence of improved stroke treatment.'),
120:('Can continuous vessel representations preserve vascular geometry and topology?','FlowAxis models adaptive interconnected vessel-axis keypoints with a geometric-topological optimization formulation.','Four three-dimensional vascular benchmarks showed improved centerline topology and boundary fidelity, with supporting theoretical convergence arguments.','Mathematical guarantees apply under stated model assumptions; benchmark performance does not guarantee safety or clinical benefit in arbitrary scans.'),
121:('Can combined PET biomarkers improve obstructive-coronary-disease diagnosis?','XGBoost integrates ten PET/CT-derived and clinical parameters, trained at one center and externally tested at three.','Among 1,664 angiography-selected patients, external-test AUC was 0.83, exceeding physicians and individual perfusion or flow biomarkers.','Selection for invasive angiography limits population generalization; retrospective diagnostic gains do not establish improved outcomes or reduced testing.'),
122:('Can slide-level labels support accurate gastric-cancer segmentation?','Geo-MIL constructs tissue-patch graphs with topological attention to prioritize diagnostic structures.','Experiments on three public gastric datasets improved both segmentation and classification over compared weakly supervised approaches.','The abstract supplies no numeric effects or cohort sizes; benchmark segmentation gains do not establish prospective pathologist assistance or patient benefit.'),
123:('Can longitudinal models predict individual myopia progression with and without intervention?','Transformer modules learn natural progression from 304,353 young people and intervention trajectories from four treatment cohorts.','Predictions generalized externally, with strong refractive and axial-length agreement and individualized modeled treatment effects.','Repeated records are not independent children; estimated intervention effects require causal assumptions and do not establish model-guided treatment superiority.'),
124:('Can embryo videos and clinical records jointly predict several IVF outcomes?','VaTEP combines time-lapse reconstruction and developmental-stage pretraining with video sampling and multitask multimodal learning.','The framework estimates heartbeat, singleton versus multiple pregnancy, and miscarriage versus live birth probabilities.','The abstract reports no sample sizes or numeric validation results; proposed reductions in failed pregnancies are not demonstrated intervention effects.'),
125:('Can kidney-transplant prediction and policy reasoning become auditable?','KT-LLM coordinates sequence-based survival modeling, recipient clustering, and policy-rule agents grounded in versioned transplant references.','Deidentified OPTN/UNOS evaluations improved evidence attribution and predictive calibration while identifying recipient subgroup heterogeneity.','The abstract gives no numeric effects or sample counts; auditable outputs do not by themselves establish policy compliance, equitable care, or patient benefit.'),
})
add({
126:('Can genetic knowledge improve osteoarthritis drug-repurposing predictions?','CausalPathKG adapts RotatE embeddings with GWAS-weighted links, pathway regularization, graph attention, and negative sampling.','An osteoarthritis graph incorporating genetic evidence from nearly two million individuals improved held-out treatment-link prediction over simpler embedding baselines.','Recovery of known links and pathway plausibility do not establish efficacy of newly nominated drugs or causal therapeutic effects.'),
127:('Can one spine CT model segment, number, and localize vertebral abnormalities across domains?','VertebraFormer combines a transformer encoder, task-specific decoders, and dynamic domain modulation on the four-source MultiSpine benchmark.','Experiments improved accuracy and robustness across three tasks, supported by perturbation, efficiency, and ablation analyses.','The abstract provides no cohort sizes or effect estimates; benchmark robustness does not establish prospective diagnostic utility.'),
128:('Can AI accelerate aneurysm volumetry before and after endovascular repair?','A segmentation network measures aneurysm, lumen, and thrombus volumes on CTA with internal/external validation and surgeon workflow assessment.','Total-aneurysm Dice reached 0.972 internally and 0.960 externally; model assistance saved about 117 seconds, or 56%, per assessment.','High volume agreement and time savings do not establish improved rupture prediction, surveillance decisions, or patient outcomes.'),
129:('Can computational surveillance identify lifitegrast adverse-event signals?','Machine learning combines FAERS reports, language-derived reaction patterns, drug-gene networks, and molecular docking.','Across 4,511 reports, the model achieved AUC 0.892 and identified 16 signals, alongside candidate regulatory genes and predicted binding interactions.','Spontaneous reporting cannot determine incidence or causality; docking and signal prediction do not validate personalized real-time medication-risk estimates.'),
130:('Do safety guardrails change language-model responses to irritability prompts?','Four models with different guardrail levels completed three irritability instruments under baseline and provoked conditions.','Lower-guardrail models increased irritability scores, whereas highly guarded models suppressed them, sometimes to zero.','Questionnaire outputs are simulated model behavior rather than human emotion; differences across models cannot isolate guardrails as the sole causal factor.'),
131:('Can video models distinguish nocturnal seizures from parasomnias?','A SlowFast network classifies sleep-related hypermotor epilepsy, arousal disorders, and REM sleep behavior disorder from recordings.','Across three data splits involving 167 individuals, mean classification accuracy was 83.3%, supporting preliminary automated event assessment.','The abstract does not establish independent prospective home validation or replacement of specialist clinical and electrophysiological diagnosis.'),
132:('Can breath-sensor AI distinguish lung cancer, gastric cancer, and healthy controls?','A hierarchical convolutional network first separates cancer from controls, then distinguishes cancer types using multimodal gas-sensor response maps.','Fivefold validation in 206 participants yielded class AUCs around 0.89–0.92 and outperformed a one-dimensional CNN.','Internal case-control validation does not establish population screening performance, particularly against benign diseases or unseen environmental exposures.'),
133:('Can a compact MRI model classify cognitive states and highlight suspicious regions?','CVTC combines scale-adaptive transformer features with coordinate-guided attribution and a visualization interface.','ADNI and other datasets showed high reported classification accuracy, with additional tumor and multiple-sclerosis tests of annotation behavior.','Attribution overlays are not independently validated Alzheimer lesions; very high image-benchmark accuracy requires scrutiny of patient-level splits and external clinical relevance.'),
134:('Can autonomous agents optimize prompts for detecting cognitive concerns in notes?','Five specialized agents coordinate prompt refinement, compared with expert-driven workflows and prevalence-reflecting validation.','The agentic method approached expert-workflow performance, but sensitivity fell from 0.91 to 0.62 between refinement and validation datasets; re-adjudication explained some apparent errors.','Distribution shift and ambiguous labels limit generalization; note detection is not a diagnosis or demonstrated benefit from screening intervention.'),
135:('Can adaptive multi-agent reasoning support multidisciplinary cancer recommendations?','EvoMDT updates prompts, consensus weights, and retrieval scope using feedback, with evidence-linked specialist agents.','Six QA benchmarks, four oncology datasets, and physician ratings favored guideline alignment and reported 30–40% faster responses, with fewer assessed safety violations.','Retrospective plan agreement and expert ratings do not establish equivalent patient outcomes to an actual multidisciplinary tumor board.'),
136:('Do language-model education tools improve preoperative and discharge outcomes?','A systematic review narratively synthesized 20 studies and assessed evaluation coverage with a four-dimensional framework.','Some studies found lower anxiety and better satisfaction, while pain, recovery, and other satisfaction outcomes often showed no significant improvement.','Uneven reporting of trustworthiness and model performance prevents attributing clinical outcomes to specific model properties or assuming uniform effectiveness.'),
137:('How do Parkinson-related brain-network changes relate to diagnosis?','A multilevel meta-analysis synthesized network topology and a separate diagnostic evidence subset.','Eighty studies involving 3,736 patients and 2,384 controls showed reduced network segregation; ten diagnostic studies yielded pooled AUC 0.86, with stronger combined-metric performance.','Medication and network-construction heterogeneity limit biomarker transfer; pooled case-control discrimination does not establish prospective clinical screening.'),
})
add({
138:('Can synthetic polyp images improve detector generalization?','Conditional StyleGAN augmentation supplements YOLOv5 training with public colorectal images.','Using over 150,000 source images, hybrid training increased internal mean average precision from 0.86 to 0.93 and flat/depressed-lesion recall from 0.72 to 0.87, with better external transfer.','Still-image improvements do not establish real-time video performance or higher adenoma detection in a patient-randomized trial.'),
139:('Can machine learning improve survival prediction for extranodal NK/T-cell lymphoma?','Sixteen algorithms were compared using clinical and pathological predictors, selecting gradient boosting for an ENKTL score.','Four cohorts totaling 977 people supported evaluation/external concordance around 0.82–0.84 and stronger risk stratification than established scores.','Discrimination and decision curves do not establish improved treatment selection or patient survival; an online calculator still requires local validation.'),
140:('How do obesity genetic risk and lifestyle relate to mortality?','Stacked machine learning builds a polygenic score using UK Biobank and Nanfang Hospital data, followed by mortality association analyses.','External obesity discrimination was modest at AUC 0.565; healthier lifestyles among genetically high-risk participants were associated with lower mortality.','The reported 59% relative mortality reduction is observational, not a randomized lifestyle effect; genetic-score prediction weakened externally.'),
141:('Can targeted ocular segmentation improve sign detection while limiting facial exposure?','DSE-Net isolates ocular structures, followed by classifiers for thyroid-eye-disease signs across multinational images.','A retrospective study of 2,360 eyes showed improved segmentation and detection relative to broader facial inputs, but external sign AUCs ranged widely from 0.556 to 0.843.','Reduced exposed image content is not guaranteed anonymity, and variable external discrimination limits claims of uniform generalizability.'),
142:('Can task-specific patient summaries improve multimodal clinical prediction and explanations?','xHAIM uses generative AI to select relevant data, summarize patients, and link predictions to patient-specific information.','On HAIM-MIMIC-MM, mean AUC across chest pathology and operative tasks increased from 0.799 to 0.913 relative to HAIM.','Linked explanations are not necessarily faithful causal accounts; retrospective benchmark gains do not establish prospective decision-support benefit.'),
143:('Can integrated molecular profiling identify aggressive prostate-cancer states and targets?','Single-cell/spatial analysis of 141,986 cells is combined with 101 candidate prognostic pipelines and SHAP interpretation.','A malignant epithelial state supported recurrence-risk prediction; PCSK1N experiments in organoids and xenografts connected the candidate to growth and androgen-therapy resistance.','Cell counts are not patient counts, and preclinical drug sensitization does not establish patient benefit from targeting PCSK1N.'),
144:('How do structural variants and chromatin architecture contribute to kidney cancer?','Multi-omics analysis maps enhancer hijacking, with experimental validation and a machine-learning prognostic signature.','The study links structural rearrangements to three-dimensional genome changes, identifies SEMA5B activation, and develops enhancer-signature-based prognosis modeling.','The abstract supplies no cohort size or predictive effect estimates; mechanistic experiments do not establish a validated clinical prognostic tool.'),
145:('Can blood transcriptomic features complement plasma biomarkers for Alzheimer detection?','Random-forest feature selection and partial-least-squares modeling derive a lactylation-related score, combined with phosphorylated tau.','Across multiple datasets and a 540-person plasma cohort, score AUC fell from 0.897 in training to 0.772 clinically; the combined marker model reached 0.859.','Cross-tissue validation and diagnostic associations do not establish population-screening performance, biological causality, or improved clinical outcomes.'),
146:('Can noninvasive AI estimate a pancreatic-tumor immune ratio linked to prognosis?','Seven models were evaluated using TCGA, CPTAC, and multicenter data, selecting the multimodal PORCELAIN region-based model.','Externally estimated neutrophil-to-T-cell ratios stratified overall and recurrence-free survival and were associated with chemotherapy response.','The abstract gives no sample sizes or numeric accuracy; prognostic associations do not establish benefit from selecting treatment according to the model.'),
147:('Can grounded ultrasound reports combine ophthalmic diagnosis with lesion localization?','A vision-language segmentation model links report generation with Segment Anything using 64,098 images and 21,355 reports from three hospitals.','External diagnostic accuracy was 71.87%, with segmentation Dice near 0.50; estimated reporting costs were much lower than specialist reporting.','Cost estimates are not realized workflow savings, and substantial external errors require specialist review despite strong text-similarity scores.'),
148:('Can a topology-aware network locate pediatric central-catheter tips more reliably?','TopNet preserves catheter continuity during radiograph segmentation, with internal and external evaluation.','Retrospective data from 1,184 PICC patients included 280 young children; the model improved segmentation and tip localization under difficult imaging conditions.','The abstract lacks numeric performance estimates; retrospective localization does not establish fewer catheter complications or prospective clinical safety.'),
149:('Can automated hospital-data curation support governed multispecialty AI research?','S-RACE combines local anonymization, NLP extraction, FHIR standardization, and an explainable-model development environment.','Data from 31,276 patients supported 19 projects; kidney-cancer and aortic-stenosis models using automatically curated data performed comparably to manually curated alternatives.','Infrastructure demonstrations and governance descriptions do not independently certify regulatory compliance, privacy guarantees, or improved outcomes from deployed models.'),
})
def main():
 rows=json.loads((ROOT/'research-cache/npj-root-abstracts.json').read_text())
 assert set(NOTES)==set(range(114,150))
 out=[]
 for i in range(114,150):
  source=rows[i];q,m,f,l=NOTES[i]
  out.append({'id':source['id'],'research_problem':q,'problem_is_excerpt':False,'ai_method':m,'study_summary':f,'outcome_summary':f,'limitations':[l],'curation_level':'curated','review_level':'abstract','field_status':{'research_problem':'manually_interpreted_original_abstract','ai_method':'manually_interpreted_original_abstract','study_summary':'manually_interpreted_original_abstract','limitations':'manually_interpreted_design_boundary'},'manual_review':'Original publisher abstract read and interpreted; no full-text review claimed.','evidence_links':[{'label':'Original abstract','url':source['url']+'#Abs1'}]})
 target=ROOT/'data/enrichment/npj-root-tail-manual.json';target.write_text(json.dumps(out,ensure_ascii=False,indent=2))
 print('Saved',len(out),'unique',len({x['id'] for x in out}))
if __name__=='__main__':main()
